// JyutpingMatcher.swift — the Cantonese sound matcher for 「喂阿寶」 (PRD §20.4.3, §25.6). Pure Swift, Foundation only.
//
// Twin of brain/ahbo/wake/matcher.py (Stage 3). Same table (wake_homophones.json, generated by
// `ahbo gen-wake-table` from PyCantonese — never edit it by hand), same rules, same fixture
// (brain/config/wake_cases.yaml). Rules:
//  * separators (Unicode general categories Z*, P*, S*, Cc, Cf) are skipped; each other Character is one syllable
//  * start of utterance only: syllable 0 must be 喂-class (wai) when require_wai
//  * then aa+bou at syllable 1 (full) · or bou at syllable 1 when allow_missing_aa (「喂寶」) · or one filler
//    syllable then aa+bou (「喂喂阿寶」, "aa bou within 2 syllables of the start after a wai")
//  * plain 「阿寶」 (aa+bou at syllable 0) only when plain_abou_wakes (off by default)
//  * the exact strings 「喂阿寶」 and 「喂，阿寶」 at the start always match
//  * reduplication guard: a bou-class syllable right after the matched bou rejects the candidate — 寶寶 is
//    "baby", so 「喂寶寶」 ("hey baby") stays asleep while 「喂寶」 wakes
//  * remainder = text after the last matched character, leading separators stripped

import Foundation

struct WakeMatchConfig: Equatable, Sendable {
    var requireWai = true
    var requireTwoUpdates = true
    var utteranceStartSilenceMs = 300
    var cooldownAfterRejectS = 5.0
    var allowMissingAa = true
    var exactOnly = false
    var plainAbouWakes = false

    /// Parses the `key: value` lines of brain/config/wake_match.yaml (bundled as-is; comments skipped).
    static func parseYAML(_ text: String) -> WakeMatchConfig {
        var kv: [String: String] = [:]
        for raw in text.split(whereSeparator: \.isNewline) {
            let line = raw.split(separator: "#", maxSplits: 1, omittingEmptySubsequences: false).first.map { String($0) } ?? ""
            let parts = line.split(separator: ":", maxSplits: 1).map { $0.trimmingCharacters(in: .whitespaces) }
            if parts.count == 2, !parts[0].isEmpty { kv[parts[0]] = parts[1] }
        }
        return WakeMatchConfig().merged(kv.mapValues { $0 as Any })
    }

    /// Overrides from a dictionary (server `welcome.config.wake` or the YAML above).
    func merged(_ d: [String: Any]) -> WakeMatchConfig {
        func bool(_ k: String) -> Bool? {
            if let b = d[k] as? Bool { return b }
            if let s = d[k] as? String { return ["true", "yes", "on"].contains(s.lowercased()) ? true : (["false", "no", "off"].contains(s.lowercased()) ? false : nil) }
            if let n = d[k] as? NSNumber { return n.boolValue }
            return nil
        }
        func num(_ k: String) -> Double? {
            if let n = d[k] as? NSNumber { return n.doubleValue }
            if let s = d[k] as? String { return Double(s) }
            return nil
        }
        var c = self
        if let v = bool("require_wai") { c.requireWai = v }
        if let v = bool("require_two_updates") { c.requireTwoUpdates = v }
        if let v = num("utterance_start_silence_ms") { c.utteranceStartSilenceMs = Int(v) }
        if let v = num("cooldown_after_reject_s") { c.cooldownAfterRejectS = v }
        if let v = bool("allow_missing_aa") { c.allowMissingAa = v }
        if let v = bool("exact_only") { c.exactOnly = v }
        if let v = bool("plain_abou_wakes") { c.plainAbouWakes = v }
        return c
    }
}

struct WakeMatch: Equatable, Sendable {
    var ok: Bool
    var remainder: String = ""
    var rule: String = ""
    var matched: String = ""
}

struct JyutpingMatcher: Sendable {
    let wai: Set<Character>
    let aa: Set<Character>
    let bou: Set<Character>
    var config: WakeMatchConfig

    static let exactStrings = ["喂阿寶", "喂，阿寶"]
    static let maxSyllables = 6

    init(wai: Set<Character>, aa: Set<Character>, bou: Set<Character>, config: WakeMatchConfig = WakeMatchConfig()) {
        self.wai = wai; self.aa = aa; self.bou = bou; self.config = config
    }

    /// Loads the generated table `{"wai":[…],"aa":[…],"bou":[…]}`.
    init(tableJSON: Data, config: WakeMatchConfig = WakeMatchConfig()) throws {
        let t = try JSONDecoder().decode([String: [String]].self, from: tableJSON)
        func set(_ k: String) -> Set<Character> { Set((t[k] ?? []).compactMap(\.first)) }
        self.init(wai: set("wai"), aa: set("aa"), bou: set("bou"), config: config)
    }

    /// From the app bundle (or another bundle, for tests).
    static func load(bundle: Bundle = .main, config: WakeMatchConfig = WakeMatchConfig()) -> JyutpingMatcher? {
        guard let url = bundle.url(forResource: "wake_homophones", withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JyutpingMatcher(tableJSON: data, config: config)
    }

    static func isSeparator(_ ch: Character) -> Bool {
        guard let s = ch.unicodeScalars.first else { return true }
        switch s.properties.generalCategory {
        case .spaceSeparator, .lineSeparator, .paragraphSeparator,
             .connectorPunctuation, .dashPunctuation, .openPunctuation, .closePunctuation,
             .initialPunctuation, .finalPunctuation, .otherPunctuation,
             .mathSymbol, .currencySymbol, .modifierSymbol, .otherSymbol,
             .control, .format:
            return true
        default:
            return false
        }
    }

    static func stripLeadingSeparators(_ s: Substring) -> String {
        String(s.drop(while: isSeparator))
    }

    func match(_ transcript: String) -> WakeMatch {
        var syl: [(ch: Character, idx: String.Index)] = []
        var i = transcript.startIndex
        while i < transcript.endIndex, syl.count < Self.maxSyllables {
            let ch = transcript[i]
            if !Self.isSeparator(ch) { syl.append((ch, i)) }
            i = transcript.index(after: i)
        }
        if syl.isEmpty { return WakeMatch(ok: false) }

        func isClass(_ set: Set<Character>, _ k: Int) -> Bool { k < syl.count && set.contains(syl[k].ch) }

        var candidates: [(rule: String, n: Int)] = []
        if syl.map({ $0.ch }).hasPrefix("喂阿寶") {     // separators already skipped in syl
            candidates.append(("exact", 3))
        }
        let plain = config.plainAbouWakes || !config.requireWai
        if !config.exactOnly && isClass(wai, 0) {
            if isClass(aa, 1) && isClass(bou, 2) { candidates.append(("full", 3)) }
            if config.allowMissingAa && isClass(bou, 1) { candidates.append(("missing_aa", 2)) }
            if isClass(aa, 2) && isClass(bou, 3) { candidates.append(("filler", 4)) }
        }
        if plain && isClass(aa, 0) && isClass(bou, 1) { candidates.append(("plain", 2)) }

        for c in candidates {
            if isClass(bou, c.n) { continue }                       // reduplication guard: 寶寶 = "baby"
            let end = transcript.index(after: syl[c.n - 1].idx)
            return WakeMatch(ok: true, remainder: Self.stripLeadingSeparators(transcript[end...]), rule: c.rule,
                             matched: String(syl.prefix(c.n).map(\.ch)))
        }
        return WakeMatch(ok: false)
    }
}
